(function(){
'use strict';
const KEY='safariPocketbookSafetyProfiles',SELECTED='safariPocketbookSafetyCountry',dialog=document.getElementById('sosDialog'),button=document.getElementById('sosButton'),form=document.getElementById('safetySetup'),country=document.getElementById('safetyCountry');let coordinates=null;
const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch(error){return{}}};const toast=message=>{const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2300)};
country.innerHTML+=(window.africanAtlas||[]).map(row=>`<option value="${row[0]}">${row[0]}</option>`).join('');country.value=localStorage.getItem(SELECTED)||'';
function profile(){return read()[country.value]||{}}
function setValue(id,value=''){document.getElementById(id).value=value}
function loadProfile(){const data=profile();setValue('trustedName',data.trustedName);setValue('trustedPhone',data.trustedPhone);setValue('guideName',data.guideName);setValue('guidePhone',data.guidePhone);setValue('emergencyPhone',data.emergencyPhone);setValue('safetyVerified',data.verified);document.getElementById('safetyConfirmed').checked=!!data.confirmed;renderReadiness()}
function renderReadiness(){const data=profile(),checks=[!!country.value,!!(data.trustedName&&data.trustedPhone),!!(data.guideName&&data.guidePhone),!!(data.emergencyPhone&&data.confirmed&&data.verified)],score=checks.filter(Boolean).length,stale=data.verified&&((Date.now()-new Date(data.verified).getTime())>90*86400000);document.getElementById('readinessScore').textContent=`${score} of 4 ready`;document.getElementById('readinessDetail').textContent=!country.value?'Choose a destination country.':score===4?(stale?'Emergency number was verified over 90 days ago; check it again.':'Contacts and locally verified emergency number saved.'):'Complete trusted contact, field contact and verified local number.';document.getElementById('shareSosStatus').textContent=data.trustedPhone?`${data.trustedName} · ${data.trustedPhone}`:'Add a trusted contact first';document.getElementById('guideStatus').textContent=data.guidePhone?`${data.guideName} · ${data.guidePhone}`:'Not configured';document.getElementById('localHelpStatus').textContent=data.emergencyPhone?`${country.value} · ${data.emergencyPhone}${stale?' · recheck':''}`:'Not configured'}
button.addEventListener('click',()=>{loadProfile();dialog.showModal()});document.querySelector('.sos-close').addEventListener('click',()=>dialog.close());document.getElementById('toggleSafetySetup').addEventListener('click',()=>{form.hidden=!form.hidden;document.getElementById('toggleSafetySetup').textContent=form.hidden?'Safety setup':'Hide setup'});country.addEventListener('change',()=>{localStorage.setItem(SELECTED,country.value);loadProfile()});
form.addEventListener('submit',event=>{event.preventDefault();if(!country.value){toast('Choose the destination country first.');return}const emergency=document.getElementById('emergencyPhone').value.trim(),confirmed=document.getElementById('safetyConfirmed').checked,verified=document.getElementById('safetyVerified').value;if(emergency&&(!confirmed||!verified)){toast('Confirm the emergency number and record when it was verified.');return}const profiles=read();profiles[country.value]={trustedName:document.getElementById('trustedName').value.trim(),trustedPhone:document.getElementById('trustedPhone').value.trim(),guideName:document.getElementById('guideName').value.trim(),guidePhone:document.getElementById('guidePhone').value.trim(),emergencyPhone:emergency,verified,confirmed,updatedAt:new Date().toISOString()};localStorage.setItem(KEY,JSON.stringify(profiles));renderReadiness();form.hidden=true;document.getElementById('toggleSafetySetup').textContent='Safety setup';toast(`${country.value} safety setup saved on this device.`)});
document.getElementById('getLocation').addEventListener('click',()=>{const label=document.getElementById('locationLabel'),detail=document.getElementById('locationDetail');if(!navigator.geolocation){label.textContent='Location unavailable';detail.textContent='This device does not provide location.';return}label.textContent='Finding your location…';detail.textContent='Keep this screen open.';navigator.geolocation.getCurrentPosition(position=>{const {latitude,longitude,accuracy}=position.coords;coordinates={latitude,longitude,accuracy};label.textContent=`${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;detail.textContent=`Accuracy approximately ${Math.round(accuracy)} metres · captured ${new Date().toLocaleTimeString()}.`},()=>{label.textContent='Location permission denied';detail.textContent='Enable location access in phone settings and try again.'},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})});
document.getElementById('shareSos').addEventListener('click',async()=>{const data=profile(),where=coordinates?`Location: https://maps.google.com/?q=${coordinates.latitude},${coordinates.longitude} (accuracy about ${Math.round(coordinates.accuracy)} m).`:'Current location is not attached.',context=country.value?`Country: ${country.value}.`:'';const text=`SOS — I may need assistance. ${context} ${where} Please confirm you received this message and contact local emergency services if necessary.`;if(!data.trustedPhone)toast('No trusted contact is configured; choose a recipient manually.');if(navigator.share){try{await navigator.share({title:'Safari SOS — assistance requested',text})}catch(error){if(error.name!=='AbortError')toast('SOS was not shared. Try again or copy the message.')}}else{try{await navigator.clipboard.writeText(text);toast('SOS message copied. You must send it and confirm receipt.')}catch(error){toast('Sharing is unavailable. Call a saved contact directly.')}}});
function call(field,label){const value=profile()[field];if(!value){toast(`${label} is not configured for ${country.value||'this country'}.`);form.hidden=false;return}location.href=`tel:${value.replace(/[^+\d]/g,'')}`}
document.getElementById('contactGuide').addEventListener('click',()=>call('guidePhone','Guide or lodge number'));document.getElementById('localHelp').addEventListener('click',()=>call('emergencyPhone','Emergency number'));loadProfile();
})();
